import React, { useCallback } from 'react';

// packages
import { Tabs, Menu } from 'antd';
import { Icon as LegacyIcon } from '@ant-design/compatible';

// assets
import CheckMarkIcon from 'public/static/sessions/checkmark.svg';

// utils
import CellOverflowTooltip from 'Utils/helpers/CellOverflowTooltip';
import { highlightSearchedText } from 'Utils/helpers/searchHighlighter';

// styles
import {
    LabelOverlayWrapper, 
    HeaderFooterContainer, 
    TabContainer, 
    TabWrapper, 
    StyledMenu,
    CustomLabelsSearchWrapper,
    CustomLabelsSearchInput,
    CustomLabelsSearchIcon,
    CustomLabelsIcon,
    CustomLabelsButton,
    NoResultsWrapper,
} from './styles';

// types
import { TLabelsDropdownOverlay, TOptions } from './types';

const extraLabelKeys = ['session_with_notes', 'session_has_video', 'session_is_viewed'];
const { ItemGroup: MenuItemGroup } = Menu;

const LabelsDropdownOverlay:React.FC<TLabelsDropdownOverlay> = (props) => {
  const { 
    header, 
    footer, 
    selectedKeys,
    disabledKeys,
    tabs, 
    handleItemClicked, 
    handleApply, 
    searchInput, 
    handleTabChange, 
    showLabelCount,
    hideFooter,
    headerStyle,
    containerStyle,
    emptyMessage,
    emptyLabelMessage,
 } = props;

  const renderLabelItem  = useCallback((label: TOptions) => {
    const { name, attribute, icon } = label;

    if (selectedKeys?.includes(name) || selectedKeys?.includes(attribute || '')) {
        return (
          <CustomLabelsIcon>
            <CheckMarkIcon />
          </CustomLabelsIcon>
        );
    } if (extraLabelKeys.includes(attribute || ''))  {
        return  icon as string;
    }
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore
    return <LegacyIcon type={icon} />;
    
  }, [selectedKeys]);

  return (
    <LabelOverlayWrapper style={containerStyle}>
        {
            header ? (
                <HeaderFooterContainer style={headerStyle}>
                    {header}
                </HeaderFooterContainer>
            ) : null
        }

        {
            emptyMessage ? (
                <i className='empty-message'>{emptyMessage}</i>
            ) : (
                <TabContainer onClick={(e) => {
                    e.stopPropagation();
                }}>
                    <TabWrapper
                        centered
                        defaultActiveKey={tabs[0].key}
                        moreIcon={null}
                        onChange={handleTabChange}
                        tabCount={tabs.length}
                    >
                        {
                            tabs.map((tab) => {
                                const {name, key, options, showSearch} = tab;
                                return(
                                <Tabs.TabPane tab={name} key={key}>
                                        <StyledMenu 
                                            selectedKeys={selectedKeys} 
                                            onClick={({key: itemkey}) => handleItemClicked && handleItemClicked(itemkey, tab)}
                                            hasTitle={showSearch}
                                        >
                                            <MenuItemGroup 
                                                title={
                                                    showSearch ? (
                                                    <CustomLabelsSearchWrapper>
                                                        <CustomLabelsSearchIcon src="/static/sessions/search.svg" alt="Search icon" />
                                                        <CustomLabelsSearchInput
                                                            placeholder="Search labels"
                                                            // eslint-disable-next-line react/jsx-props-no-spreading
                                                            {...searchInput}
                                                        />
                                                    </CustomLabelsSearchWrapper>
                                                    ) : undefined
                                                }
                                            >
                                                {
                                                    options.map((option) => (
                                                    <Menu.Item key={option.attribute || option.name}
                                                        disabled={disabledKeys?.includes(option.name || option.attribute || '')}
                                                    >
                                                        {renderLabelItem(option)}

                                                        <CellOverflowTooltip
                                                            width={showLabelCount ? 150 : 170}
                                                            text={option.name}
                                                            value={highlightSearchedText(option.name, searchInput?.value)}
                                                            className='tooltip'
                                                        />

                                                        {
                                                            showLabelCount ? (
                                                            <span className='label-count'>
                                                                {option.count}
                                                            </span>) : null
                                                        }
                                                    </Menu.Item>
                                                    ))
                                                }
                                                {
                                                    options.length === 0 && (
                                                        <NoResultsWrapper>{emptyLabelMessage || 'No matching filter'}</NoResultsWrapper>
                                                    )
                                                }
                                            </MenuItemGroup>
                                        </StyledMenu>
                                </Tabs.TabPane> 
                                )
                            })
                        }
                    </TabWrapper>
                </TabContainer>
            )
        }

        {
            footer ? (
                <HeaderFooterContainer isFooter onClick={e => e.stopPropagation()}>
                    {footer}
                </HeaderFooterContainer>
            ) : (
                !hideFooter && <CustomLabelsButton onClick={handleApply}>Apply</CustomLabelsButton>
            )
        }
    </LabelOverlayWrapper>
  )
}

export default LabelsDropdownOverlay;