import React, { useState, useCallback, useMemo } from "react";

// packages
import some from 'lodash/some';
import { rollbar } from 'components/common/rollbar';
import { useSelector, useDispatch } from "react-redux";
import { useMutation, useQuery, useQueryClient } from "react-query";

import CommonApi from "services/commonApi";
import { addSessionId } from 'redux/actions/common';
import { addSegmentV2 } from 'redux/actions/filter';
import { trackPageViews } from 'redux/actions/trackingReport';
import { callSessionStatisticsAPI } from 'redux/actions/megaFilter'

import {
  userNewMarkLabel,
  addNewLabelOnUser,
} from 'components/features/users/hooks/useUserItem';

import {
  deleteNewLabelV2,
  updateNewCustomLabelV2,
  addNewLabelOnSessionPageV2,
  markNewLabelOnSessionPageV2,
} from 'components/features/sessions/hooks/useSessionItems';

const preDefined = [
  'rage_tap',
  'rage_quit',
  'session_crashed',
  'ui_freeze',
];
const extraCustomLabelKeys = ['custom_label', 'user_custom_label'];

export const useGetCustomLabelsQuery = (appId) => useQuery(['customLabels', appId], () => CommonApi.getNewCustomLabel(appId), {
  enabled: Boolean(appId),
});

export const useCustomLabelApi = () => {
  const queryClient = useQueryClient();
  const { currentAppReducer } = useSelector((state) => state);
  const { _id: appId } = currentAppReducer;
  const customLabelQueryKey = useMemo(() => ['customLabels', appId], [appId]);

  // user label mutations
  const addUserLabelMutation = useMutation({
    mutationFn: (payload) => addNewLabelOnUser(payload),
    onSuccess: () => {
      queryClient.invalidateQueries(customLabelQueryKey);
    },
    onError: (error) => {
      rollbar.error(error);
    }
  });
  const markUserLabelMutation = useMutation({
    mutationFn: (payload) => userNewMarkLabel(payload),
    onSuccess: () => {
      queryClient.invalidateQueries(customLabelQueryKey);
    },
    onError: (error, payload) => {
      rollbar.error(error, {
        source: 1,
        payload, 
        errorMessage: error?.response?.data,
      });
    }
  });

  // session label mutations
  const addSessionLabelMutation = useMutation({
    mutationFn: (payload) => addNewLabelOnSessionPageV2(payload),
    onSuccess: () => {
      queryClient.invalidateQueries(customLabelQueryKey);
    },
    onError: (error, payload) => {
      rollbar.error(error, {
        source: 2,
        payload, 
        errorMessage: error?.response?.data,
      });
    }
  });

  const updateLabelMutation = useMutation({
    mutationFn: (payload) => updateNewCustomLabelV2(payload),
    onSuccess: () => {
      queryClient.invalidateQueries(customLabelQueryKey);
    },
    onError: (error) => {
      rollbar.error(error);
    }
  });

  const deleteLabelMutation = useMutation({
    mutationFn: (payload) => deleteNewLabelV2(payload),
    onSuccess: () => {
      queryClient.invalidateQueries(customLabelQueryKey);
    },
    onError: (error) => {
      rollbar.error(error);
    }
  });

  const markSessionLabelMutation = useMutation({
    mutationFn: (payload) => markNewLabelOnSessionPageV2(payload),
    onSuccess: () => {
      queryClient.invalidateQueries(customLabelQueryKey);
    },
    onError: (error, payload) => {
      rollbar.error(error, {
        source: 3,
        payload, 
        errorMessage: error?.response?.data,
      });
    }
  });

  return {
    addUserLabel: addUserLabelMutation.mutateAsync,
    markUserLabel: markUserLabelMutation.mutateAsync,
    addSessionLabel: addSessionLabelMutation.mutateAsync,
    markSessionLabel: markSessionLabelMutation.mutateAsync,
    updateLabel: updateLabelMutation.mutateAsync,
    deleteLabel: deleteLabelMutation.mutateAsync,
  };
};

const useCustomLabels = () => {
    const dispatch = useDispatch(); 
    const { appFilter, currentAppReducer } = useSelector((state) => state);
    const { session } = appFilter;
    const sessionSegment = session.segment;
    const {_id: appId} = currentAppReducer;
    const { data: existingCustomLabels } = useGetCustomLabelsQuery(appId);
    const customLabelQueryKey = useMemo(() => ['customLabels', appId], [appId]);

    const [selectedLabels, setSelectedLabels] = useState({
      sessionLabels: [],
      userLabels: [],
    });
    const [labelSearch, setLabelSearch] = useState({
      sessionLabels: '',
      userLabels: '',
    })

    const customLabels = useMemo(() => {
      const fetchedData = existingCustomLabels?.data || [];
      return fetchedData;
    }, [existingCustomLabels]);

    const sessionLabels = useMemo(() => customLabels.filter((label) => label.labelType === 'session'), [customLabels]);
    const userLabels = useMemo(() => customLabels.filter((label) => label.labelType === 'user'), [customLabels]);
    const filteredSessionLabels = useMemo(() => sessionLabels.filter((label) => label.name.toLowerCase().indexOf(labelSearch.sessionLabels.toLowerCase()) >= 0), [sessionLabels, labelSearch.sessionLabels]);
    const filteredUserLabels = useMemo(() => userLabels.filter((label) => label.name.toLowerCase().indexOf(labelSearch.userLabels.toLowerCase()) >= 0), [userLabels, labelSearch.userLabels]);
    const megaFilterCustomLabels = useMemo(
      () => existingCustomLabels?.data || [],
      [existingCustomLabels?.data]
    );
    const megaFilterSessionLabels = useMemo(
      () =>
        megaFilterCustomLabels?.filter(
          (label) => label.labelType === 'session'
        ),
      [megaFilterCustomLabels]
    );
    const megaFilteredSessionLabels = useMemo(
      () =>
        megaFilterSessionLabels?.filter(
          (label) =>
            label.name
              .toLowerCase()
              .indexOf(labelSearch.sessionLabels.toLowerCase()) >= 0
        ),
      [megaFilterSessionLabels, labelSearch.sessionLabels]
    );

    // the same name for session and user labels is not allowed
    const getLabelTypeFromValue = useCallback((value) => {
      const label = customLabels.find((item) => item.name === value);
      return label?.labelType;
    }, [customLabels]);

    const checkExistingLabel = useCallback(
      (value) => {
        const normalizedStr = value.replace(/\s+/g, ' ');
        const trimmedValue = normalizedStr.trim();

        return some(customLabels, (label) =>
          label.name.toLowerCase() === trimmedValue.toLowerCase()
        );
      },
      [customLabels]
    );
    
    const compareLabels = useCallback((selectedValues, a, b) => {
      if (selectedValues?.includes(a.attribute || a.name) && !selectedValues?.includes(b.attribute || b.name)) {
        return -1;
      }
      if (selectedValues?.includes(b.attribute || b.name) && !selectedValues?.includes(a.attribute || a.name)) {
        return 1;
      }
      return 0
    }, []);

    const resetSearch = () => {
      setLabelSearch({
        sessionLabels: '',
        userLabels: '',
      })
    }

    const sortLabels = useCallback(() => {
      filteredSessionLabels?.sort((a, b) => compareLabels(selectedLabels.sessionLabels, a, b));
      filteredUserLabels?.sort((a, b) => compareLabels(selectedLabels.userLabels, a, b));
      megaFilteredSessionLabels?.sort((a, b) => compareLabels(selectedLabels.sessionLabels, a, b));
    }, [compareLabels, filteredSessionLabels, filteredUserLabels, megaFilteredSessionLabels, selectedLabels.sessionLabels, selectedLabels.userLabels])

    const handleLabel = React.useCallback((sessionKeys, userKeys, callback) => {
      dispatch(addSessionId([]))
      let segment
      const keysWithoutPredefined = sessionKeys.filter((key) => !preDefined.includes(key))
      const segmentValue = sessionSegment || []
  
      if (!sessionKeys.length && !userKeys.length) {
        dispatch(
          addSegmentV2(
            [],
            'session-filter'
          )
        );
        dispatch(callSessionStatisticsAPI());
        return null
      }
  
      const segmentsWithoutCustomLabels = segmentValue.filter((obj) => !extraCustomLabelKeys.includes(obj.attribute));
      
      let newSessionLabelSegments = []
      let newUserLabelSegments = []
  
      keysWithoutPredefined.forEach((key) => {
        segment = {
          attribute: 'custom_label',
          operator: 'has_any',
          value: [key],
          table: 'session',
        };
        newSessionLabelSegments = [...newSessionLabelSegments, segment];
      });
      if (userKeys && userKeys.length) {
        userKeys.forEach((key) => {
          segment = {
            attribute: 'user_custom_label',
            operator: 'has_any',
            value: [key],
            table: 'appuser',
          };
          newUserLabelSegments = [...newUserLabelSegments, segment];
        });
      }
      const valSegments = [...segmentsWithoutCustomLabels, ...newSessionLabelSegments, ...newUserLabelSegments]
      
      dispatch(
        trackPageViews(null, {
          eventName: 'apply_quick_filter',
          track_type: 'event',
          eventProperty: {
            type: 'custom_label',
            featureFlagQuickbar: true,
            oldSetting: segmentValue,
            newSetting: valSegments,
          },
        })
      )
  
      dispatch(
        addSegmentV2(
          valSegments.length > 0 ? valSegments : undefined,
          'session-filter'
        )
      )
  
      dispatch(callSessionStatisticsAPI());

      resetSearch();
  
      if (typeof callback === 'function') callback()
      return null
    }, [dispatch, sessionSegment])

    const cachedValues = useMemo(
      () => ({
        customLabels,
        handleLabel,
        sessionSegment,
        selectedLabels,
        setSelectedLabels,
        filteredSessionLabels,
        filteredUserLabels,
        compareLabels,
        labelSearch,
        setLabelSearch,
        resetSearch,
        sortLabels,
        megaFilterCustomLabels,
        megaFilterSessionLabels,
        megaFilterUserLabels: userLabels,
        sessionLabels,
        userLabels,
        megaFilteredSessionLabels,
        getLabelTypeFromValue,
        customLabelQueryKey,
        checkExistingLabel,
      }),
      [
        customLabels,
        handleLabel,
        sessionSegment,
        selectedLabels,
        filteredSessionLabels,
        filteredUserLabels,
        sortLabels,
        megaFilterCustomLabels,
        sessionLabels,
        userLabels,
        megaFilteredSessionLabels,
        customLabelQueryKey,
      ]
    );

    return cachedValues;
}

export default useCustomLabels;