export const getTableType = (type) => {
  switch (type) {
    case 'user':
      return 'userTable';
    case 'screen':
      return 'screenTable';
    case 'event':
      return 'eventTable';
    case 'nocodeEvent':
      return 'eventTable';
    case 'issue':
      return 'issueTable';
    default:
      return 'sessionTable';
  }
}

