export const reorder = (list, startIndex, endIndex) => {
  const result = Array.from(list)
  const [removed] = result.splice(startIndex, 1)
  result.splice(endIndex, 0, removed)

  return result
}

export const calculateColumnWidth = (parentType, tableColWidth, obj) => {
  let colArray = [];
  if (parentType === 'sessionsList') {
    if (tableColWidth.sessionTableColWidth.length) {
      colArray = tableColWidth?.sessionTableColWidth?.filter(row => row.attribute === obj.attribute)
    }
  }
  if (parentType === 'aiSessionsList') {
    if (tableColWidth.sessionTableColWidth.length) {
      colArray = tableColWidth?.sessionTableColWidth?.filter(row => row.attribute === obj.attribute)
    }
  }
  if (parentType === 'usersList') {
    if (tableColWidth.userTableColWidth.length) {
      colArray = tableColWidth?.userTableColWidth?.filter(row => row.attribute === obj.attribute)
    }
  }
  if (parentType === 'screensList') {
    if (tableColWidth.screenTableColWidth.length) {
      colArray = tableColWidth?.screenTableColWidth?.filter(row => row.attribute === obj.attribute)
    }
  }
  if (parentType === 'issues') {
    if (tableColWidth.issueTableColWidth.length) {
      colArray = tableColWidth?.issueTableColWidth?.filter(row => row.attribute === obj.attribute)
    }
  }
  if (parentType === 'eventsList') {
    if (tableColWidth.eventTableColWidth.length) {
      colArray = tableColWidth?.eventTableColWidth?.filter(row => row.attribute === obj.attribute)
    }
  }
  return colArray.length ? colArray[0].colWidth : 0
}

export const resizeTableColumn = (tableState, tableHeader) => {
  const currentTableColumnWidths = [];
  tableHeader.map(header => {
    const selectedColumn = header.attribute;
    if (header.isVisible) {
      let colParentWidth;
      if (['sessionhashofuser', 'sessiondate', 'devicemodel', 'sessionid', 'recordedonuserdate', 'timeforuser', 'columndate'].includes(selectedColumn)) {
        colParentWidth = tableState.defaultTableColumnWidth.largeColWidth
      }
      else if (['eventcount', 'userdevice', 'totalgesture', 'crashed', 'platform', 'screencount', 'country'].includes(selectedColumn)) {
        colParentWidth = tableState.defaultTableColumnWidth.smallColWidth
      }
      else {
        colParentWidth = tableState.defaultTableColumnWidth.mediumColWidth
      }
      currentTableColumnWidths.push({
        attribute: selectedColumn,
        colWidth: colParentWidth,
        colResize: false,
      })
    }
  })
  return currentTableColumnWidths;
}

