export const getPlatform = platform => platform === 1 ? 'Android' : platform === 2 ? 'iOS' : "-"

/* convert time duration from seconds to actual format */
export const getTimeDuration = (seconds = 0) => {
  const SECONDS_PER_DAY = 86400;
  const HOURS_PER_DAY = 24;
  const days = Math.floor(seconds / SECONDS_PER_DAY);
  const remainderSeconds = seconds % SECONDS_PER_DAY;
  const hms = new Date(remainderSeconds * 1000).toISOString().substring(11, 19).replace(/^(\d+)/, h => `${Number(h) + days * HOURS_PER_DAY}`.padStart(2, '0'));
  const convertedDuration = hms.split(':');
  return `${convertedDuration[0] > 0 ? `${convertedDuration[0]}:` : ''}${convertedDuration[1]}${`:${  convertedDuration[2]}`}`
}

// create a non-colliding random number
export const generateUUID = _ => {
  let d = new Date().getTime();
  const uuid = "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (c) => {
    const r = (d + Math.random() * 16) % 16 | 0;
    d = Math.floor(d / 16);
    return (c === "x" ? r : (r & 0x3) | 0x8).toString(16);
  });
  return uuid;
}

export const getSessionIdWithDate = (sessionIds, sessionList) => {
  const idsWithDateList = [];
  sessionIds.map((sessionId) => {
      const result = sessionList.find(session => session.sessionid === sessionId);
      idsWithDateList.push({ id: sessionId, uploaded_on: result.sessionUploadedDateTime })
  })
  return idsWithDateList;
}

export const getScreenSessionIdWithDate = (sessionIds, sessionList) => {
  const idsWithDateList = [];
  sessionIds.map((sessionId) => {
      const result = sessionList.find(session => session.sessionid === sessionId);
      idsWithDateList.push({ id: sessionId, uploaded_on: result.uploadedDateTime })
  })
  return idsWithDateList;
}

export const getUserIdWithDate = (userIds, userList) => {
  const idsWithDateList = [];
  userIds.map((userId) => {
      const result = userList.find(user => user.uxcamuserid === userId);
      idsWithDateList.push({ id: userId, first_seen: result.firstSeen, last_seen: result.lastSeen })
  })
  return idsWithDateList;
}

