export function getRageIcon(eventName) {
  return eventName === 'Single Tap' ? '/static/gestures/rage.svg' : '/static/gestures/double-rage.svg'
}

/**
* function that returns an event name to return gesture icon
* @param {string} eventName
* @param {boolean} isRage
* @param {boolean} isEvent
*/
export function identifyEventName(eventName, isRage, isEvent, isSmartEvent, isScreenEvent) {
  if (isScreenEvent) {
    return 'smart_screenvisit_event'
  }
  if ( isSmartEvent ) {
    return 'no-code event'
  } 
  if (isEvent) {
    return eventName === 'UI Freeze' ? 'ui freeze' : 'event';
  } 
  if (isRage) {
    switch(eventName) {
      case 'Single Tap':
        return 'single rage';
      case 'Double Tap':
        return 'double rage';
      default:
        return 'rage';
    }
  } else return eventName
}

export function getActionType(action) {
  const { type } = action;
  return {
    isEvent: type === 'sdk_event',
    isSmartEvent: type === 'smart_gesture_event',
    isGesture: type === 'gesture',
    isScreenEvent: type === 'smart_screenvisit_event',
  }
}

export const getAnrMenu = (sessionDetail) => {
  const actionValues = [];
  const sessionObj = sessionDetail?.screenTimeline?.activities;
  sessionObj?.forEach((ses) => {
    const { actions } = ses;
    if (actions instanceof Array && actions?.length > 0) {
      actions?.forEach((action) => {
        const { isEvent } = getActionType(action);
        if (action.name === 'UI Freeze' || (action.name === 'ANR' && isEvent)) {
          actionValues.push(action);
        }
      });
    }
  });
  return actionValues;
}

