import React from 'react';
import styled from "styled-components";

const Highlight = styled.i`
    color: #5D97FF;
    font-style: normal;
`

export const highlightSearchedText= (text, searchValue) => {
    const searchedText = searchValue.toLowerCase().replaceAll(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const regExp = new RegExp(`(${searchedText.replace(/ /g, '\\s')})`, 'gi');
    return text
    .split(regExp)
    .map((part) => {
        if (part.toLowerCase() === searchedText) {
        return <Highlight>{part}</Highlight>;
        } if (part.includes('\u00A0')) {
        return part.split('\u00A0').join(' ');
        } 
        return part;
        
    });
};