import { useCallback, useMemo } from 'react';
import { RootStateOrAny, useSelector } from 'react-redux';
import { useQuery } from 'react-query';
import IssueApi from 'services/issueApi';
import { graphApiMapper } from '../variables';
import { IGraphApiMapper, IIssueTypeMapper, IIssueHookProps } from './types';

export const issueTypeMapper = {
  crashes: 'crash',
  freezes: 'uifreeze',
  exceptions: 'exception',
};

const useIssueListAPI = (sortRequestOrder: IIssueHookProps [], page: number) => {
  const {
    currentAppReducer: { _id: appId },
    urlReducer: { issueType, issueid, url },
    appFilter: {
      issue: { segment: issueSegment },
      dateSegment,
    },
  } = useSelector((state: RootStateOrAny) => state);

  const issueId = useMemo(() => {
    if (!issueid) return undefined;
    if (issueid.includes(' ')) {
      return url.split('/')[6].replace('?', '');
    }
    return issueid;
  }, [issueid, url]);

  const getIssueList = useCallback( async () => {
    const listType = issueId ? 'detail_list' : 'list';
    const urlPath = `${
      graphApiMapper[issueType as keyof IGraphApiMapper]
    }${listType}`;
    const filters = issueId
      ? [
          ...issueSegment,
          ...[
            {
              attribute: `${
                issueTypeMapper[issueType as keyof IIssueTypeMapper]
              }_id`,
              operator: 'equal',
              value: issueId,
            },
          ],
        ]
      : [...issueSegment];
    const newFormData = {
      appid: appId,
      date_range: dateSegment,
      filters,
      order_by: sortRequestOrder,
      page,
    };
    return IssueApi.fetchIssueGraph(newFormData, urlPath);
  }, [appId, dateSegment, issueId, issueSegment, issueType, page, sortRequestOrder]);

  const issueListQueryKey = useMemo(
    () => [
      'issue_list',
      appId,
      issueType,
      issueSegment,
      sortRequestOrder,
      page,
      dateSegment,
    ],
    [appId, issueType, issueSegment, sortRequestOrder, page, dateSegment]
  );

  const issueListDetailQueryKey = useMemo(
    () => [
      'issue_detail_list',
      appId,
      issueId,
      issueType,
      issueSegment,
      sortRequestOrder,
      page,
      dateSegment,
    ],

    [
      appId,
      issueId,
      issueType,
      issueSegment,
      sortRequestOrder,
      page,
      dateSegment,
    ]
  );

  const { isLoading: isListLoading, data: issueListData, isPreviousData: isListDataPrev } = useQuery(
    issueListQueryKey,
    () => getIssueList(),
    {
      enabled: !!appId && issueId === undefined && !!issueType,
      keepPreviousData: true,
    }
  );

  const { isLoading: isDetailListLoading, data: issueListDetailData, isPreviousData: isDetailDataPrev } = useQuery(
    issueListDetailQueryKey,
    () => getIssueList(),
    {
      enabled: !!appId && issueId !== undefined && !!issueType,
      keepPreviousData: true,
    }
  );

  const isAPILoading = useMemo(
    () =>
      isListLoading ||
      isDetailListLoading ||
      isListDataPrev ||
      isDetailDataPrev,
    [isDetailDataPrev, isDetailListLoading, isListDataPrev, isListLoading]
  );
  const issueList = useMemo(() => issueListData?.data?.data, [issueListData]);
  const issueListDetail = useMemo(() => issueListDetailData?.data?.data, [issueListDetailData]);

  return { isAPILoading, issueList, issueListDetail, issueListQueryKey, issueListDetailQueryKey };
};

export default useIssueListAPI;
