import { axiosInstance } from './globalInstance';

class IssueApi {
  static async fetchIssueBox(data, url) {
    const response = await axiosInstance({
      method: 'POST',
      url: `${process.env.PYTHON_API_URL}/${url}`,
      data,
      withCredentials: true,
    });
    return response;
  }

  static async fetchIssueSession(data, url) {
    const response = await axiosInstance({
      method: 'POST',
      url: `${process.env.PYTHON_API_URL}/${url}`,
      data,
      withCredentials: true,
      validateStatus(status) {
        return status >= 200 && status < 401;
      },
    });
    return response;
  }

  static async fetchIssueDetailStackTrace(data, url) {
    const response = await axiosInstance({
      method: 'POST',
      url: `${process.env.PYTHON_API_URL}/${url}`,
      data,
      withCredentials: true,
      validateStatus(status) {
        return status >= 200 && status < 401;
      },
    });
    return response;
  }

  static async fetchIssueGraph(data, url) {
    const response = await axiosInstance.post(
      `${process.env.PYTHON_API_URL}/${url}`,
      data,
      {
        withCredentials: true,
      }
    );
    return response;
  }

  static async fetchDetailIssueGraph(data, url) {
    const response = await axiosInstance.post(
      `${process.env.PYTHON_API_URL}/${url}`,
      data,
      {
        withCredentials: true,
      }
    );
    return response;
  }

  static async fetchIssueTable(data, url) {
    const response = await axiosInstance({
      method: 'POST',
      url: `${process.env.PYTHON_API_URL}/${url}`,
      data,
      withCredentials: true,
    });
    return response;
  }

  static async fetchIssueDetailBox(data, url) {
    const response = await axiosInstance({
      method: 'POST',
      url: `${process.env.PYTHON_API_URL}/${url}`,
      data,
      withCredentials: true,
    });
    return response;
  }

  static async fetchIssueDetailTable(data, url) {
    const response = await axiosInstance({
      method: 'POST',
      url: `${process.env.PYTHON_API_URL}/${url}`,
      data,
      withCredentials: true,
    });
    return response;
  }

  static async fetchSessionIssueGraph(data) {
    const response = await axiosInstance.post(
      `${process.env.PYTHON_API_URL}/sessions`,
      data,
      {
        withCredentials: true,
      }
    );
    return response;
  }
}

export default IssueApi;
