export const NoCustomUserIdMessage = "Custom user ID was not set for this user."

// * Show Custom User ID if set else show uxcamuserid
export const getUserId = (
    { customUserId, uxcamuserid }: { customUserId: string | undefined, uxcamuserid: string }) => {
        const config = {
        customUserId,
        uxcamuserid,
        indicator: '',
        info: NoCustomUserIdMessage ,
        selector: 'customUserId',
        availableUserId: uxcamuserid
    }
    if (!customUserId) {
        config.indicator = '*' // * if customUserId is not set
    }
    if (customUserId) {
        config.availableUserId = customUserId // *first priority is customUserId
    }
    return config
}

export const UsernameInfoMessage = "Custom user ID or UXCam user ID"
export const UXCamUserIdInfoMessage = "User ID set in the UXCam database"