import { useQuery, useMutation, useQueryClient } from 'react-query';
import { useSelector } from 'react-redux';
import { axiosInstance } from 'services/globalInstance';
import SessionTableApi from 'services/sessionTableApi';
import { useFeatureFlag } from 'uxcam-frontend-components';

const getSessionItems = async ({ postBody }) => SessionTableApi.getV2SessionsList(postBody)
const sortColumns = async (postBody) =>
  axiosInstance.post(
    `${process.env.PYTHON_API_URL}/preference/column-sort-order`,
    postBody,
    {
      withCredentials: true,
      credentials: 'include',
    }
  )

export const useSessionItems = (postBody, parentType) => {
  const { _id: currentAppId, isAIEnabled } = useSelector((state) => state.currentAppReducer) || {};
  const isCurrentAppReady = postBody?.appid && postBody.appid === currentAppId && !isAIEnabled;

  return useQuery(['sessionItems', postBody], () => getSessionItems({ postBody }), {
    refetchOnMount: false,
    retry: 3,
    cacheTime: 0,
    enabled: parentType !== 'usersList' && isCurrentAppReady,
    keepPreviousData: true,
  });
}

export const useSessionSort = (postBody) =>
  useQuery('sortSession', () => sortColumns(postBody), {
    enabled: false,
    retry: false,
  });


