export const useChangeColumn = () => {
  let sessionQueryKey = ''
  let aiSessionQueryKey = ''
  let userQueryKey = ''
  let eventQueryKey = ''
  let nocodeEventQueryKey = ''
  try {
    sessionQueryKey = ['sessionItems', JSON.parse(localStorage.getItem('sessionsListReqBody'))]
    aiSessionQueryKey = ['aiSessionItems', JSON.parse(localStorage.getItem('aiSessionsListReqBody'))]
    userQueryKey = ['userList', JSON.parse(localStorage.getItem('usersListReqBody'))]
    eventQueryKey = ['eventList', JSON.parse(localStorage.getItem('eventsListReqBody'))]
    nocodeEventQueryKey = ['nocodeEventList', JSON.parse(localStorage.getItem('eventsListReqBody'))]
  } catch (err) {
    // silent fail
  }
  const mapReqBody = {
    session: sessionQueryKey,
    aiSession: aiSessionQueryKey,
    user: userQueryKey,
    event: eventQueryKey,
    nocodeEvent: nocodeEventQueryKey
  }
  const queryClient = useQueryClient();
  return useMutation(
    async ({ data, url }) =>
      axiosInstance.post(`${process.env.PYTHON_API_URL}/${url}`, data, {
        withCredentials: true,
        credentials: 'include',
        enabled: false,
      }),
    {
      onSuccess: (data, variables) => {
        const { type } = variables;
        const queryKey = mapReqBody[type]
        const newHeader = data?.data?.data?.preferenceData?.header || data?.data?.data?.preference;
        const newSortOrder = data?.data?.data?.preferenceData?.sortOrder;
        const previousValue = queryClient.getQueryData(queryKey);
        if (previousValue) {
          queryClient.setQueryData(queryKey, (old) => {
            if (!old?.data?.data) return old;
            return {
              ...old,
              data: {
                ...old.data,
                data: {
                  ...old.data.data,
                  header: newHeader,
                  ...(newSortOrder && { orderBy: newSortOrder }),
                },
              },
            };
          });
        }
        if (newSortOrder) {
          const localStorageKeyMap = {
            session: 'sessionsListReqBody',
            aiSession: 'aiSessionsListReqBody',
            user: 'usersListReqBody',
            event: 'eventsListReqBody',
            nocodeEvent: 'eventsListReqBody',
          };
          try {
            const storageKey = localStorageKeyMap[type];
            if (storageKey) {
              const reqBody = JSON.parse(localStorage.getItem(storageKey));
              if (reqBody) {
                reqBody.orderBy = newSortOrder;
                localStorage.setItem(storageKey, JSON.stringify(reqBody));
              }
            }
          } catch (err) {
            // silent fail
          }
        }
        if (type === 'aiSession') {
          queryClient.invalidateQueries({ queryKey: ['aiSessionItems'] });
        }
        return previousValue;
      },
    }
  );
};

