import React, { useState, useRef, useEffect } from 'react';
import { Tooltip } from 'antd';
import styled from 'styled-components';

const TextWrapper = styled.div`
  overflow: hidden;
  white-space: pre;
  text-overflow: ellipsis;
  width: ${({ width }) => `${width}`}px;
`;

const CellOverflowTooltip = (props) => {
  const textElementRef = useRef();
  const {
    width,
    text,
    className = '',
    value,
    showTooltip = false,
    tooltipElement,
    placement = 'right',
  } = props;
  const [isEllipsisShown, setEllipsisShown] = useState(showTooltip);
  useEffect(() => {
    setEllipsisShown(
      textElementRef.current.scrollWidth > textElementRef.current.clientWidth
    );
  }, [width]);
  return isEllipsisShown || tooltipElement ? (
      <Tooltip title={tooltipElement || text} placement={placement}>
          <TextWrapper width={width} ref={textElementRef} className={className}>
            {value}
          </TextWrapper>
      </Tooltip>
  ) : (
    <TextWrapper width={width} ref={textElementRef} className={className}>
      {value}
    </TextWrapper>
  );
};

export default CellOverflowTooltip;
