import { useQuery } from 'react-query';

import { axiosInstance } from 'services/globalInstance';
import UserApi from 'services/userApi';
import { defaultRefetchInterval } from 'Utils/constants/index';

const getUserList = async (postBody) => UserApi.getUsersList(postBody)

export const useUserList = (postBody, parentType, enabled) => useQuery(['userList', postBody], () => getUserList(postBody), {
    refetchInterval: defaultRefetchInterval,
    retry: 3,
    cacheTime: 0,
    enabled: enabled &&  ![ 'sessionsList', 'aiSessionsList' ].includes( parentType ),
    keepPreviousData: true,
});

export const getUserSortedList = (postBody) =>
  axiosInstance.post(`${process.env.PYTHON_API_URL}/preference/column-sort-order`, postBody, {
    withCredentials: true,
    credentials: 'include',
});

export const useUserSortedItems = (postBody) => getUserSortedList(postBody);

export const addNewLabelOnUser = async (data) => {
    const response = await axiosInstance.post(
        `${process.env.PYTHON_API_URL}/label/user/add_custom_label`,
        data,
        {
            withCredentials: true,
            credentials: 'include',
        }
    )
    return response?.data;
}

export const userNewMarkLabel = async (data) =>{
    const response = await axiosInstance.post(
        `${process.env.PYTHON_API_URL}/label/user/update_custom_label`,
        data,
        {
            withCredentials: true,
            credentials: 'include',
        }
    )
    return response?.data
}